<?php
declare(strict_types=1);
namespace Zandu\Tests\Modules\CashManagement\Domain;
use DateTimeImmutable;use PHPUnit\Framework\TestCase;use Zandu\Modules\CashManagement\Domain\CashSession\{CashSession,CashSessionStatus};use Zandu\Platform\Decimal\BrickDecimalFactory;use Zandu\Platform\Identity\SymfonyUuidFactory;use Zandu\SharedKernel\Identity\{ActorId,CashRegisterId,CashSessionId,OrganizationId,StoreId};use Zandu\SharedKernel\Money\{Currency,Money};
final class CashSessionTest extends TestCase{public function testOpenAndClose():void{$f=new SymfonyUuidFactory();$m=fn(string $v)=>Money::fromString($v,Currency::fromCode('XAF'),new BrickDecimalFactory());$s=CashSession::open(CashSessionId::fromString('0198d601-1111-7111-8111-111111111111',$f),OrganizationId::fromString('0198d602-1111-7111-8111-111111111111',$f),StoreId::fromString('0198d603-1111-7111-8111-111111111111',$f),CashRegisterId::fromString('0198d604-1111-7111-8111-111111111111',$f),ActorId::fromString('0198d605-1111-7111-8111-111111111111',$f),$m('100'),new DateTimeImmutable());$s->close($m('95'),$m('100'),ActorId::fromString('0198d606-1111-7111-8111-111111111111',$f),new DateTimeImmutable());self::assertSame(CashSessionStatus::Closed,$s->status());self::assertSame('-5',$s->discrepancy()?->amount()->toString());}public function testExpectedBalanceUsesOpeningAndNetMovement():void{$f=new SymfonyUuidFactory();$m=fn(string $v)=>Money::fromString($v,Currency::fromCode('XAF'),new BrickDecimalFactory());$s=CashSession::open(CashSessionId::fromString('0198d607-1111-7111-8111-111111111111',$f),OrganizationId::fromString('0198d608-1111-7111-8111-111111111111',$f),StoreId::fromString('0198d609-1111-7111-8111-111111111111',$f),CashRegisterId::fromString('0198d60a-1111-7111-8111-111111111111',$f),ActorId::fromString('0198d60b-1111-7111-8111-111111111111',$f),$m('100'),new DateTimeImmutable());self::assertSame('125',$s->calculateExpectedBalance($m('25'))->amount()->toString());}}
